from roster_expansion import clean_mask as base_clean_mask
def clean_mask(im,*args,**kwargs):
 items=base_clean_mask(im,*args,**kwargs)
 for item in items:
  a=np.array(item['image']).copy();rgb=a[:,:,:3].astype('int16')
  # Hokane has no white shirt: large white voids between limbs are background.
  white=(rgb.min(2)>205)&(rgb.max(2)-rgb.min(2)<28)&(a[:,:,3]>0)
  labels,n=ndi.label(white)
  for k,sl in enumerate(ndi.find_objects(labels),1):
   if not sl:continue
   yy,xx=sl;mask=labels[sl]==k
   if yy.start>item['h']*.40 and yy.stop-yy.start>15 and xx.stop-xx.start>15 and mask.sum()>500:
    a[sl][mask,3]=0
  if kwargs.get('rope'):
   red=(rgb[:,:,0]>95)&(rgb[:,:,0]>rgb[:,:,1]*1.55)&(rgb[:,:,0]>rgb[:,:,2]*1.6)&(a[:,:,3]>0)
   labels,n=ndi.label(red)
   for k,sl in enumerate(ndi.find_objects(labels),1):
    if not sl:continue
    yy,xx=sl
    if yy.start>item['h']*.4 and xx.stop-xx.start>4*(yy.stop-yy.start) and xx.stop-xx.start>25:a[sl][labels[sl]==k,3]=0
  item['image']=Image.fromarray(a)
 return items

