  a=np.array(im).copy();v=a.astype('int16');yy=np.arange(h)[:,None]
  dust=(yy>h*.80)&(v[:,:,0]>85)&(v[:,:,1]>65)&(v[:,:,2]>40)&(v[:,:,0]>v[:,:,2]*1.25)&(v[:,:,1]>v[:,:,2]*1.12)
